type Member struct {

    // --- identity ---
    ID         string  
    Identifier string  // matric or staff no., UNIQUE
    Email      string  // citext: Ada@ and ada@ are one
    Faculty, Department, Level string

    // --- entitlement ---
    Role     Role             // checked on the SERVER
    Category *MemberCategory  // null for staff
    Status   UserStatus       // suspended cannot sign in

    // --- credentials ---
    PasswordHash        string  // Argon2id. Never sent.
    MustChangePassword  bool    // travels in the token
    TokensInvalidBefore time.Time

    // --- provenance ---
    IsSynthetic bool  // simulator-created
    CreatedAt, UpdatedAt time.Time  // TIMESTAMPTZ
}

// What a category is allowed to do.
const (
    Undergraduate MemberCategory = "undergraduate"
    Postgraduate  MemberCategory = "postgraduate"
    Staff         MemberCategory = "staff"
)

// Limits live in one table, not in the handlers.
var Terms = map[MemberCategory]LoanTerm{
    Undergraduate: {MaxLoans: 2, Days: 14},
    Postgraduate:  {MaxLoans: 4, Days: 21},
    Staff:         {MaxLoans: 6, Days: 28},
}

type Loan struct {
    CopyID, UserID string
    BorrowedAt, DueAt time.Time
    ReturnedAt *time.Time  // nil means still out

    // Note what is ABSENT: no IsOverdue flag.
    // Overdue is DueAt < now, computed on read.
}
